(function initPatientSession() {
    const stored = localStorage.getItem('loggedInPatient');
    const headerLabel = document.getElementById('headerUserLabel');
    const patientIdField = document.getElementById('patientId');
    const symPatientIdField = document.getElementById('symPatientId');

    if (!stored) {
        // No one is logged in — send them to log in first.
        headerLabel.innerText = 'Not logged in — redirecting to login...';
        window.location.href = '/login';
        return;
    }

    try {
        const patient = JSON.parse(stored);
        // Use email as the unique, stable identifier (matches how the
        // backend keys scans and looks up /api/patient_profile/{email}).
        const identifier = patient.email;

        patientIdField.value = identifier;
        symPatientIdField.value = identifier;
        headerLabel.innerText = 'Logged in as ' + (patient.full_name || identifier);
    } catch (err) {
        console.error('Could not parse stored patient session:', err);
        window.location.href = '/login';
    }
})();
